/* A port of the gallery-size arithmetic in analysis/calibration.py.
 *
 * The measured table -- SFACE_FMR, every (threshold, false-match rate) pair
 * counted over FairFace's 4.77e9 impostor pairs -- is not retyped here. It
 * arrives in js/constants.js, generated by tools/build_static.py straight
 * from the Python module, as Python's shortest round-tripping repr of each
 * float. Retyping a measurement is how a published number stops being the
 * measured one.
 *
 * Ported: fmrAt, galleryRisk, recommendThreshold, riskTable, describe. Those
 * are what the page shows. calibration.py also carries the age-estimator and
 * samples-per-person calibration; neither is on this page, so neither is
 * ported -- an unported function cannot disagree with anything, and a ported
 * one nobody checks is just a second place to be wrong.
 */
var Calibration = (function () {
  'use strict';

  var D = CALIBRATION_DATA;
  var XS = D.fmr.map(function (row) { return row[0]; });
  var YS = D.fmr.map(function (row) { return row[1]; });

  /* Python's bisect.bisect_left: the leftmost index at which `value` could be
   * inserted and keep the list sorted. bisect_right would differ at exactly
   * the measured thresholds -- the nine values a reader is most likely to
   * type -- so this is the half of the port most worth getting right.
   */
  function bisectLeft(array, value) {
    var lo = 0;
    var hi = array.length;
    while (lo < hi) {
      var mid = (lo + hi) >> 1;
      if (array[mid] < value) { lo = mid + 1; } else { hi = mid; }
    }
    return lo;
  }

  function fmrAt(threshold) {
    if (threshold <= XS[0]) { return YS[0]; }
    if (threshold >= XS[XS.length - 1]) { return YS[YS.length - 1]; }
    var i = bisectLeft(XS, threshold);
    var x0 = XS[i - 1];
    var x1 = XS[i];
    var y0 = YS[i - 1];
    var y1 = YS[i];
    var frac = (threshold - x0) / (x1 - x0);
    return y0 + frac * (y1 - y0);
  }

  function galleryRisk(threshold, gallerySize) {
    if (gallerySize < 2) { return 0.0; }
    return 1.0 - Math.pow(1.0 - fmrAt(threshold), gallerySize - 1);
  }

  /* The loosest measured threshold whose gallery-wide risk stays under
   * maxRisk, and whether there is one at all. `reachable: false` is the
   * honest answer that this recogniser does not scale to that gallery -- not
   * a number to use anyway, which is what returning the strictest without
   * the flag would look like. */
  function recommendThreshold(gallerySize, maxRisk) {
    for (var i = 0; i < XS.length; i += 1) {
      var risk = galleryRisk(XS[i], gallerySize);
      if (risk <= maxRisk) {
        return { threshold: XS[i], risk: risk, reachable: true };
      }
    }
    var strictest = XS[XS.length - 1];
    return {
      threshold: strictest,
      risk: galleryRisk(strictest, gallerySize),
      reachable: false
    };
  }

  function riskTable(gallerySize) {
    return D.fmr.map(function (row) {
      return {
        threshold: row[0],
        fmrPerPair: row[1],
        galleryRisk: galleryRisk(row[0], gallerySize)
      };
    });
  }

  /* Python's f"{x:.0%}" and f"{x:.2%}": multiply by 100 and round
   * half-to-even, which is not what JavaScript's toFixed does. Ported
   * because the sentence below is displayed verbatim and the build compares
   * it as a string. */
  function percent(value, places) {
    return roundHalfEven(value * 100, places).toFixed(places) + '%';
  }

  function roundHalfEven(value, places) {
    var scale = Math.pow(10, places);
    var scaled = value * scale;
    var floor = Math.floor(scaled);
    var diff = scaled - floor;
    var rounded;
    if (Math.abs(diff - 0.5) < 1e-9) {
      rounded = (floor % 2 === 0) ? floor : floor + 1;
    } else {
      rounded = Math.round(scaled);
    }
    return rounded / scale;
  }

  function describe(gallerySize, maxRisk) {
    var found = recommendThreshold(gallerySize, maxRisk);
    var threshold = formatThreshold(found.threshold);
    if (!found.reachable) {
      return 'With ' + gallerySize + ' people enrolled, even the strictest ' +
        'measured threshold (' + threshold + ') leaves a ' +
        percent(found.risk, 0) + ' chance of a false match. SFace ' +
        'embeddings alone are not enough at this scale -- add a second ' +
        'factor (PIN, badge) rather than tightening further.';
    }
    return 'With ' + gallerySize + ' people enrolled, threshold ' +
      threshold + ' keeps the chance of any false match at ' +
      percent(found.risk, 2) + ' (target ' + percent(maxRisk, 0) +
      '). Calibrated on ' + D.corpus + '.';
  }

  /* Python prints a float with `str()`, which gives the shortest repr that
   * round-trips: 0.3 not 0.300, 0.725 not 0.72500000000000009. JavaScript's
   * default number-to-string is the same shortest-round-trip rule, so this
   * agrees -- except that Python writes `0.3` where JavaScript also writes
   * `0.3`. Kept as a named function so the build has one place to compare. */
  function formatThreshold(value) {
    return String(value);
  }

  return {
    fmrAt: fmrAt,
    galleryRisk: galleryRisk,
    recommendThreshold: recommendThreshold,
    riskTable: riskTable,
    describe: describe,
    thresholds: XS,
    corpus: D.corpus,
    reference: D.reference,
    disparity: D.disparity
  };
}());
